exec('\nfrom __future__ import annotations\n\nimport time, warnings, xml.etree.ElementTree as ET\nfrom pathlib import Path\nfrom urllib.parse import quote_plus\nimport datetime as dt\n\nimport numpy as np\nimport pandas as pd\nimport streamlit as st\nimport yfinance as yf\nimport requests\nimport plotly.graph_objects as go\nimport plotly.express as px\n\nfrom sklearn.linear_model import Ridge, ElasticNet, HuberRegressor\nfrom sklearn.ensemble import RandomForestRegressor, ExtraTreesRegressor, GradientBoostingRegressor, VotingRegressor\nfrom sklearn.metrics import mean_squared_error\n\nwarnings.filterwarnings("ignore")\nROOT = Path(__file__).resolve().parents[1]\n\n# --------------------------\n# Built-in fallbacks\n# --------------------------\nDEFAULT_MATERIALS = {\n    "Copper": {"long_name":"Copper — industrial demand and electrification", "tickers":["HG=F","CPER","COPX"], "family":"industrial_metals", "role":"construction, grids, EVs, manufacturing", "weight":0.11},\n    "Aluminum": {"long_name":"Aluminum — aerospace and energy-intensive manufacturing", "tickers":["ALI=F","AA"], "family":"industrial_metals", "role":"aerospace, transport, smelting energy", "weight":0.09},\n    "IronOre": {"long_name":"Iron ore — steel-chain and China construction", "tickers":["TIO=F","RIO","BHP","VALE"], "family":"steel_chain", "role":"steel production and China cycle", "weight":0.075},\n    "Steel": {"long_name":"Steel — producers and industrial capex", "tickers":["SLX","MT","NUE","X"], "family":"steel_chain", "role":"construction, manufacturing, capex", "weight":0.065},\n    "CokingCoal": {"long_name":"Coking coal — metallurgical coal for steelmaking", "tickers":["HCC","BTU","ARCH"], "family":"steel_chain", "role":"steel input", "weight":0.045},\n    "ThermalCoal": {"long_name":"Thermal coal — power-generation stress", "tickers":["BTU","CEIX","WHC.AX"], "family":"energy_inputs", "role":"power generation and energy security", "weight":0.04},\n    "Lithium": {"long_name":"Lithium — battery supply chain", "tickers":["LIT","ALB","SQM","PLL"], "family":"battery_materials", "role":"batteries and EV supply chain", "weight":0.075},\n    "Cobalt": {"long_name":"Cobalt — battery cathode and geopolitical proxy", "tickers":["COB.AX","GLEN.L","VALE"], "family":"battery_materials", "role":"battery cathodes and geopolitical supply", "weight":0.045},\n    "Graphite": {"long_name":"Graphite — battery anode and China export-control proxy", "tickers":["NMG","SYAAF","TGR.AX"], "family":"battery_materials", "role":"battery anodes and China processing", "weight":0.045},\n    "RareEarths": {"long_name":"Rare earths — magnets, EVs, wind and defense", "tickers":["REMX","MP","LYC.AX"], "family":"rare_earths", "role":"magnets and defense electronics", "weight":0.09},\n    "Neodymium": {"long_name":"Neodymium — NdFeB magnet proxy", "tickers":["REMX","MP","LYC.AX"], "family":"rare_earths", "role":"EV/wind magnets", "weight":0.045},\n    "Dysprosium": {"long_name":"Dysprosium — high-temperature magnet proxy", "tickers":["REMX","MP","LYC.AX"], "family":"rare_earths", "role":"defense and high-temp magnets", "weight":0.04},\n    "Titanium": {"long_name":"Titanium — aerospace/defense structural material", "tickers":["ATI","TROX","CRS","TITN"], "family":"aerospace_defense_materials", "role":"aerospace structures", "weight":0.07},\n    "Tungsten": {"long_name":"Tungsten — hard-metal tooling and defense", "tickers":["TUNG.L","ALMTF"], "family":"aerospace_defense_materials", "role":"tooling and defense", "weight":0.04},\n    "Uranium": {"long_name":"Uranium — nuclear fuel and energy security", "tickers":["URA","URNM","CCJ"], "family":"energy_security", "role":"nuclear fuel", "weight":0.07},\n    "Oil": {"long_name":"WTI crude oil — fuel, transport and inflation", "tickers":["CL=F","USO","XLE"], "family":"energy_inputs", "role":"fuel and geopolitics", "weight":0.10},\n    "BrentOil": {"long_name":"Brent oil — global oil and Middle East/Europe risk", "tickers":["BZ=F","BNO"], "family":"energy_inputs", "role":"global oil benchmark", "weight":0.08},\n    "NaturalGas": {"long_name":"Natural gas — power and manufacturing energy cost", "tickers":["NG=F","UNG","BOIL"], "family":"energy_inputs", "role":"power cost and industrial energy", "weight":0.08},\n    "Gold": {"long_name":"Gold — safe-haven and geopolitical stress", "tickers":["GC=F","GLD"], "family":"precious_stress", "role":"safe haven and real rates", "weight":0.07},\n    "Silver": {"long_name":"Silver — precious/industrial hybrid", "tickers":["SI=F","SLV"], "family":"precious_industrial", "role":"solar, electronics and precious metals", "weight":0.045},\n    "Platinum": {"long_name":"Platinum — catalyst and hydrogen proxy", "tickers":["PL=F","PPLT"], "family":"precious_industrial", "role":"auto catalysts and hydrogen", "weight":0.04},\n    "Palladium": {"long_name":"Palladium — catalyst and Russia supply risk", "tickers":["PA=F","PALL"], "family":"precious_industrial", "role":"auto catalysts and supply risk", "weight":0.04},\n}\nDEFAULT_MACRO = {\n    "USDIndex":"DX-Y.NYB", "VIX":"^VIX", "US10Y":"^TNX", "US13Week":"^IRX",\n    "HighYieldCredit":"HYG", "InvestmentGradeCredit":"LQD",\n    "EURUSD":"EURUSD=X", "USDCNY":"CNY=X", "USDJPY":"JPY=X",\n    "FreightProxy":"BDRY", "EnergyEquity":"XLE", "Semiconductors":"SOXX"\n}\nDEFAULT_INDICES = {\n    "USA":{"SP500":"^GSPC","Nasdaq100":"^NDX","Russell2000":"^RUT","DowJones":"^DJI","Industrials":"XLI","Materials":"XLB","Energy":"XLE","AerospaceDefense":"ITA"},\n    "Europe":{"DAX":"^GDAXI","CAC40":"^FCHI","FTSE100":"^FTSE","FTSEMIB":"FTSEMIB.MI","EuropeETF":"VGK"},\n    "China_HK":{"CSI300":"000300.SS","SSEComposite":"000001.SS","HangSeng":"^HSI","ChinaLargeCap":"FXI"},\n    "Japan":{"Nikkei225":"^N225","JapanETF":"EWJ"},\n    "Global":{"MSCIWorldProxy":"URTH","EmergingMarkets":"EEM","GlobalIndustrials":"EXI","GlobalMaterials":"MXI"}\n}\nFUTURES_UNIVERSE = {\n    "WTI crude oil future":"CL=F", "Brent oil future":"BZ=F", "Natural gas future":"NG=F",\n    "Copper future":"HG=F", "Gold future":"GC=F", "Silver future":"SI=F",\n    "Platinum future":"PL=F", "Palladium future":"PA=F", "Iron ore future/proxy":"TIO=F",\n    "US Dollar Index":"DX-Y.NYB", "VIX Index":"^VIX", "US 10Y yield":"^TNX",\n    "Gold ETF":"GLD", "Silver ETF":"SLV", "Oil ETF":"USO", "Natural gas ETF":"UNG",\n    "Uranium ETF":"URA", "Rare Earth ETF":"REMX", "Lithium/Battery ETF":"LIT", "Steel ETF":"SLX"\n}\nDEFAULT_GEO_TERMS = ["critical minerals","rare earth","war","Iran","Middle East","oil","gas","LNG","gold","silver","VIX","China","Taiwan","sanctions","export controls","Strait of Hormuz"]\nDEFINITIONS = {\n    "Universal interval mode": "V10 automatically adapts period, shock windows and feature creation so the app works from 1-minute views to 10-year daily views.",\n    "GCMSI": "Global Critical Materials Stress Index. A combined stress gauge from materials, energy, precious metals, macro and volatility features.",\n    "Z-score": "How unusual a move is versus recent history. 0 is normal, +2 is unusually high/up-stress, -2 is unusually low/easing.",\n    "Prediction horizon": "How far ahead the model predicts. 1d + horizon 10 means roughly 10 daily bars. 5m + horizon 12 means roughly 60 minutes.",\n    "Fallback features": "If material configs or futures fail, V10 builds features from downloaded tickers themselves, so the app does not crash.",\n}\n\n# --------------------------\n# Loaders\n# --------------------------\ndef load_yaml(path, fallback):\n    try:\n        import yaml\n        p = ROOT / path\n        if p.exists():\n            data = yaml.safe_load(p.read_text(encoding="utf-8")) or fallback\n            return data\n    except Exception:\n        pass\n    return fallback\n\ndef load_csv(path, fallback):\n    p = ROOT / path\n    try:\n        if p.exists():\n            return pd.read_csv(p).drop_duplicates()\n    except Exception:\n        pass\n    return fallback\n\ndef normalize_materials(data):\n    mats = data.get("materials", data) if isinstance(data, dict) else {}\n    if not mats:\n        return DEFAULT_MATERIALS\n    # If config is broken/empty, merge defaults under user config.\n    merged = DEFAULT_MATERIALS.copy()\n    merged.update(mats)\n    return merged\n\ndef normalize_macro(data):\n    raw = data.get("macro_proxies", data) if isinstance(data, dict) else {}\n    if not raw:\n        return DEFAULT_MACRO\n    out = DEFAULT_MACRO.copy()\n    for k, v in raw.items():\n        out[k] = v.get("ticker", v) if isinstance(v, dict) else v\n    return out\n\ndef normalize_indices(data):\n    return data.get("indices", data) if isinstance(data, dict) and data else DEFAULT_INDICES\n\ndef fallback_exposure():\n    return pd.DataFrame([\n        {"asset":"SPY","full_name":"SPDR S&P 500 ETF Trust","theme":"US market benchmark","region":"USA"},\n        {"asset":"XME","full_name":"SPDR S&P Metals & Mining ETF","theme":"Mining/metals","region":"USA"},\n        {"asset":"COPX","full_name":"Global X Copper Miners ETF","theme":"Copper miners","region":"Global"},\n        {"asset":"ITA","full_name":"iShares U.S. Aerospace & Defense ETF","theme":"Aerospace/defense","region":"USA"},\n        {"asset":"XAR","full_name":"SPDR S&P Aerospace & Defense ETF","theme":"Aerospace supply chain","region":"USA"},\n        {"asset":"PRNT","full_name":"The 3D Printing ETF","theme":"Additive manufacturing ETF","region":"Global"},\n        {"asset":"SOXX","full_name":"iShares Semiconductor ETF","theme":"Semiconductors","region":"USA"},\n        {"asset":"GLD","full_name":"SPDR Gold Shares","theme":"Gold / safe haven","region":"Global"},\n        {"asset":"SLV","full_name":"iShares Silver Trust","theme":"Silver / industrial precious","region":"Global"},\n        {"asset":"USO","full_name":"United States Oil Fund","theme":"Oil / fuel","region":"Global"},\n        {"asset":"UNG","full_name":"United States Natural Gas Fund","theme":"Gas / energy","region":"Global"},\n        {"asset":"URA","full_name":"Global X Uranium ETF","theme":"Uranium / nuclear","region":"Global"},\n        {"asset":"LIT","full_name":"Global X Lithium & Battery Tech ETF","theme":"Battery materials","region":"Global"},\n        {"asset":"REMX","full_name":"VanEck Rare Earth/Strategic Metals ETF","theme":"Rare earths","region":"Global"},\n        {"asset":"SLX","full_name":"VanEck Steel ETF","theme":"Steel","region":"Global"},\n    ])\n\nmaterials_cfg = normalize_materials(load_yaml("config/materials_universe.yml", {"materials": DEFAULT_MATERIALS}))\nmacro_cfg = normalize_macro(load_yaml("config/macro_series_config.yml", {"macro_proxies": DEFAULT_MACRO}))\nindices_cfg = normalize_indices(load_yaml("config/global_index_config.yml", {"indices": DEFAULT_INDICES}))\ngeo_cfg = load_yaml("config/geopolitical_keywords.yml", {"default_terms": DEFAULT_GEO_TERMS, "themes": {}})\nnews_sources = load_yaml("config/news_sources.yml", {"rss_sources": {}}).get("rss_sources", {})\nexposure = load_csv("data/exposure_score_table.csv", fallback_exposure())\ncompany_universe = load_csv("data/manufacturing_company_universe.csv", pd.DataFrame())\n\n# --------------------------\n# Utilities\n# --------------------------\ndef material_tickers(materials):\n    out = []\n    for spec in materials.values():\n        ticks = spec.get("tickers", [spec.get("ticker")]) if isinstance(spec, dict) else [str(spec)]\n        out += [t for t in ticks if isinstance(t, str) and t.strip()]\n    return out\n\ndef flatten_indices(idx):\n    rows = []\n    for region, mp in idx.items():\n        if isinstance(mp, dict):\n            for name, ticker in mp.items():\n                rows.append({"region": region, "name": name, "ticker": ticker})\n    return pd.DataFrame(rows)\n\ndef universal_period(interval, requested):\n    # yfinance can do long daily data; intraday is limited. This prevents invalid combinations.\n    if interval == "1m":\n        return requested if requested in ["1d","5d"] else "5d"\n    if interval in ["2m","5m","15m","30m","60m","90m"]:\n        return requested if requested in ["1d","5d","1mo","3mo","6mo"] else "60d"\n    return requested\n\ndef adaptive_shock_window(n_rows, requested):\n    if n_rows < 20:\n        return max(2, n_rows // 4)\n    if n_rows < 80:\n        return max(3, min(requested, n_rows // 5))\n    if n_rows < 250:\n        return max(5, min(requested, n_rows // 8))\n    return max(5, min(requested, 100))\n\ndef interval_delta(interval, horizon):\n    if interval.endswith("m"):\n        return dt.timedelta(minutes=int(interval[:-1]) * horizon)\n    if interval == "1d":\n        return dt.timedelta(days=horizon)\n    return dt.timedelta(days=horizon)\n\ndef valid_until(last_idx, interval, horizon):\n    try:\n        return pd.Timestamp(last_idx) + interval_delta(interval, horizon)\n    except Exception:\n        return "next horizon window"\n\n@st.cache_data(ttl=20, show_spinner=False)\ndef download_prices(tickers, period, interval):\n    tickers = sorted(set([t for t in tickers if isinstance(t, str) and t.strip()]))\n    if not tickers:\n        return pd.DataFrame()\n    raw = yf.download(tickers, period=period, interval=interval, auto_adjust=True, progress=False, threads=False)\n    if raw.empty:\n        return pd.DataFrame()\n    if isinstance(raw.columns, pd.MultiIndex):\n        if "Close" in raw.columns.get_level_values(0):\n            pxs = raw["Close"].copy()\n        else:\n            pxs = raw.xs("Close", axis=1, level=1, drop_level=True).copy()\n    else:\n        pxs = raw[["Close"]].copy()\n        if len(tickers) == 1:\n            pxs.columns = tickers\n    return pxs.dropna(axis=1, how="all").ffill().dropna(how="all")\n\ndef zscore(s, window):\n    window = max(2, int(window))\n    mean = s.rolling(window, min_periods=max(2, window // 3)).mean()\n    std = s.rolling(window, min_periods=max(2, window // 3)).std()\n    out = (s - mean) / std\n    return out.replace([np.inf, -np.inf], np.nan)\n\ndef resolve_materials(prices, materials):\n    rows, resolved = [], {}\n    for name, spec in materials.items():\n        ticks = spec.get("tickers", [spec.get("ticker")]) if isinstance(spec, dict) else [str(spec)]\n        selected = next((t for t in ticks if t in prices.columns), None)\n        if selected:\n            resolved[name] = selected\n        rows.append({\n            "material": name,\n            "long_name": spec.get("long_name", name) if isinstance(spec, dict) else name,\n            "selected_ticker": selected or "MISSING",\n            "candidate_tickers": ", ".join([str(t) for t in ticks if t]),\n            "family": spec.get("family", "material") if isinstance(spec, dict) else "material",\n            "role": spec.get("role", "") if isinstance(spec, dict) else "",\n            "weight": float(spec.get("weight", .03)) if isinstance(spec, dict) else .03,\n        })\n    return resolved, pd.DataFrame(rows)\n\ndef build_features(prices, materials, macro, shock_window):\n    n = len(prices)\n    shock = adaptive_shock_window(n, shock_window)\n    f = pd.DataFrame(index=prices.index)\n    meta = []\n    resolved, proxy_table = resolve_materials(prices, materials)\n\n    for name, ticker in resolved.items():\n        spec = materials.get(name, {})\n        col = f"MAT:{name}"\n        ret = prices[ticker].pct_change(max(1, min(shock, max(1, n//4))))\n        f[col] = zscore(ret, shock)\n        meta.append({\n            "feature": col, "long_name": spec.get("long_name", name), "ticker": ticker,\n            "family": spec.get("family", "material"), "weight": float(spec.get("weight", .03)),\n            "definition": spec.get("role", "")\n        })\n\n    for name, ticker in macro.items():\n        if ticker in prices.columns:\n            col = f"MACRO:{name}"\n            ret = prices[ticker].pct_change(max(1, min(shock, max(1, n//4))))\n            f[col] = zscore(ret, shock)\n            meta.append({"feature": col, "long_name": name, "ticker": ticker, "family": "macro", "weight": .04, "definition": "macro/market stress proxy"})\n\n    # Robust fallback: if material/macro features failed, create generic features from downloaded tickers.\n    valid_cols = [c for c in f.columns if f[c].notna().sum() >= max(3, min(20, n//5))]\n    if len(valid_cols) == 0:\n        for ticker in prices.columns[:40]:\n            px = prices[ticker].dropna()\n            if len(px) >= 8:\n                col = f"PX:{ticker}"\n                ret = prices[ticker].pct_change(max(1, min(shock, max(1, len(px)//4))))\n                f[col] = zscore(ret, max(2, min(shock, max(2, len(px)//3))))\n                meta.append({"feature": col, "long_name": f"Fallback price feature for {ticker}", "ticker": ticker, "family": "fallback_price", "weight": .02, "definition": "auto-built because material/macro configs did not produce enough usable features"})\n\n    # Drop all-empty columns, but do not require all features to be non-null simultaneously.\n    f = f.dropna(axis=1, how="all")\n    if f.empty:\n        return f, pd.DataFrame(meta), proxy_table, shock, "No usable downloaded feature series."\n\n    # Weighted index.\n    meta_df = pd.DataFrame(meta)\n    feature_cols = [c for c in f.columns if c in set(meta_df.get("feature", []))]\n    if feature_cols:\n        weights = {}\n        for _, r in meta_df.iterrows():\n            weights[r["feature"]] = float(r.get("weight", .02))\n        weighted = []\n        denom = 0\n        for c in feature_cols:\n            if c in f.columns:\n                w = weights.get(c, .02)\n                weighted.append(f[c].fillna(0) * w)\n                denom += w\n        f["GCMSI"] = sum(weighted) / denom if denom else f[feature_cols].mean(axis=1)\n    else:\n        f["GCMSI"] = f.mean(axis=1)\n\n    # Families\n    if not meta_df.empty and "family" in meta_df:\n        for fam in sorted(meta_df["family"].dropna().unique()):\n            cols = meta_df.loc[meta_df["family"] == fam, "feature"].tolist()\n            cols = [c for c in cols if c in f.columns]\n            if cols:\n                f[f"FAMILY:{fam}"] = f[cols].mean(axis=1)\n\n    if "MACRO:VIX" in f.columns:\n        f["REGIME:RiskOff"] = (f["GCMSI"].fillna(0) + f["MACRO:VIX"].fillna(0)) / 2\n    if "MACRO:USDIndex" in f.columns:\n        f["REGIME:USDPressure"] = (f["GCMSI"].fillna(0) + f["MACRO:USDIndex"].fillna(0)) / 2\n\n    # Keep rows where at least one feature exists; fill small gaps with 0 for model stability.\n    f = f.replace([np.inf, -np.inf], np.nan)\n    f = f.dropna(how="all")\n    if len(f) < 5:\n        return pd.DataFrame(), meta_df, proxy_table, shock, "Feature table too short after cleaning."\n    return f, meta_df, proxy_table, shock, "OK"\n\ndef plot_lines(df, title, ytitle="Value", normalize=False):\n    if df.empty:\n        st.warning("No data for this chart.")\n        return\n    x = df.copy().ffill().dropna(how="all")\n    if normalize and len(x):\n        x = x / x.iloc[0]\n    fig = go.Figure()\n    for col in x.columns:\n        fig.add_trace(go.Scatter(x=x.index, y=x[col], mode="lines", name=str(col), hovertemplate=f"{col}<br>%{{x}}<br>%{{y:.4f}}<extra></extra>"))\n    fig.update_layout(title=title, xaxis_title="Time", yaxis_title=ytitle, legend_title="Ticker / signal", hovermode="x unified", height=460)\n    st.plotly_chart(fig, use_container_width=True)\n\ndef plot_bar(series, title):\n    if series.empty:\n        st.warning("No data for this chart.")\n        return\n    s = series.dropna().sort_values()\n    fig = px.bar(x=s.values, y=s.index, orientation="h", title=title, labels={"x":"Value", "y":"Signal"})\n    fig.update_layout(height=max(420, 25*len(s)))\n    st.plotly_chart(fig, use_container_width=True)\n\ndef explain_box(title, bullets):\n    with st.expander(f"How to read this: {title}", expanded=True):\n        for b in bullets:\n            st.markdown(f"- {b}")\n\n# News\n@st.cache_data(ttl=240, show_spinner=False)\ndef gdelt(query, max_records):\n    try:\n        r = requests.get("https://api.gdeltproject.org/api/v2/doc/doc", params={"query": query, "mode": "ArtList", "format": "json", "maxrecords": max_records, "sort": "HybridRel"}, timeout=12)\n        if r.status_code != 200:\n            return pd.DataFrame()\n        return pd.DataFrame([{"title": a.get("title",""), "source": "GDELT / " + a.get("domain",""), "country": a.get("sourceCountry",""), "date": a.get("seendate",""), "url": a.get("url",""), "source_type": "GDELT"} for a in r.json().get("articles", [])])\n    except Exception:\n        return pd.DataFrame()\n\n@st.cache_data(ttl=600, show_spinner=False)\ndef google_news_rss(query, max_records=40):\n    try:\n        url = "https://news.google.com/rss/search?q=" + quote_plus(query) + "&hl=en-US&gl=US&ceid=US:en"\n        r = requests.get(url, timeout=10, headers={"User-Agent":"MatQuantLab/1.0"})\n        if r.status_code != 200:\n            return pd.DataFrame()\n        root = ET.fromstring(r.content)\n        rows = []\n        for it in root.findall(".//item")[:max_records]:\n            rows.append({"title": (it.findtext("title") or "").strip(), "source": "Google News RSS", "country": "", "date": (it.findtext("pubDate") or "").strip(), "url": (it.findtext("link") or "").strip(), "source_type": "Google News RSS"})\n        return pd.DataFrame(rows)\n    except Exception:\n        return pd.DataFrame()\n\n@st.cache_data(ttl=900, show_spinner=False)\ndef rss_fetch(sources, max_per=10):\n    rows, status = [], []\n    for name, spec in sources.items():\n        url = spec.get("url", "") if isinstance(spec, dict) else str(spec)\n        focus = spec.get("focus", "") if isinstance(spec, dict) else ""\n        ok, count = False, 0\n        try:\n            r = requests.get(url, timeout=10, headers={"User-Agent":"MatQuantLab/1.0"})\n            if r.status_code == 200:\n                root = ET.fromstring(r.content)\n                items = root.findall(".//item")[:max_per]\n                ok, count = True, len(items)\n                for it in items:\n                    rows.append({"title": (it.findtext("title") or "").strip(), "source": name, "country": "", "date": (it.findtext("pubDate") or "").strip(), "url": (it.findtext("link") or "").strip(), "focus": focus, "source_type": "RSS"})\n        except Exception:\n            ok = False\n        status.append({"source": name, "url": url, "focus": focus, "ok": ok, "articles_loaded": count})\n    return pd.DataFrame(rows), pd.DataFrame(status)\n\ndef score_news(news):\n    if news.empty:\n        return 0.0, pd.DataFrame()\n    # If config themes exist, use them; otherwise built-in terms.\n    themes = geo_cfg.get("themes", {})\n    if not themes:\n        themes = {\n            "war_conflict": {"long_name":"War/conflict", "weight":1.6, "words":["war","conflict","missile","drone","air strike"]},\n            "middle_east_iran": {"long_name":"Middle East/Iran/Hormuz", "weight":1.8, "words":["iran","middle east","hormuz","red sea","houthis"]},\n            "energy": {"long_name":"Fuel/gas/energy", "weight":1.3, "words":["oil","fuel","gas","lng","opec","uranium"]},\n            "critical_minerals": {"long_name":"Critical minerals", "weight":1.3, "words":["critical minerals","rare earth","lithium","cobalt","nickel","graphite","titanium"]},\n            "precious": {"long_name":"Gold/silver", "weight":1.0, "words":["gold","silver","safe haven","bullion"]},\n        }\n    titles = " ".join(news["title"].fillna("").astype(str)).lower()\n    rows, score = [], 0\n    for theme, spec in themes.items():\n        words = spec.get("words", []) if isinstance(spec, dict) else spec\n        weight = float(spec.get("weight", 1)) if isinstance(spec, dict) else 1\n        long_name = spec.get("long_name", theme) if isinstance(spec, dict) else theme\n        count = sum(titles.count(str(w).lower()) for w in words)\n        rows.append({"theme": theme, "long_name": long_name, "mentions": count, "weighted_score": count*weight})\n        score += count*weight\n    return min(score/14, 4.0), pd.DataFrame(rows).sort_values("weighted_score", ascending=False)\n\n# ML\ndef model_candidates():\n    return {\n        "Ridge": Ridge(alpha=8),\n        "ElasticNet": ElasticNet(alpha=.01, l1_ratio=.2, random_state=42),\n        "Huber": HuberRegressor(epsilon=1.35, alpha=.0001),\n        "RandomForest": RandomForestRegressor(n_estimators=180, max_depth=5, random_state=42),\n        "ExtraTrees": ExtraTreesRegressor(n_estimators=220, max_depth=5, random_state=42),\n        "GradientBoosting": GradientBoostingRegressor(random_state=42, max_depth=3),\n        "Ensemble": VotingRegressor([\n            ("ridge", Ridge(alpha=8)),\n            ("rf", RandomForestRegressor(n_estimators=120, max_depth=4, random_state=42)),\n            ("gb", GradientBoostingRegressor(random_state=42, max_depth=2)),\n        ])\n    }\n\ndef fit_eval(model, Xtr, ytr, Xte, yte):\n    model.fit(Xtr, ytr)\n    pred = model.predict(Xte)\n    corr = pd.Series(pred).corr(pd.Series(yte.values))\n    corr = 0 if pd.isna(corr) else float(corr)\n    rmse = float(mean_squared_error(yte, pred)**.5)\n    vol = max(float(ytr.std()), 1e-6)\n    score = corr - 0.10*min(rmse/vol, 5)\n    return model, pred, corr, rmse, score\n\ndef feature_importance(model, feat_cols):\n    if hasattr(model, "feature_importances_"):\n        return pd.Series(model.feature_importances_, index=feat_cols).sort_values(ascending=False)\n    if hasattr(model, "coef_"):\n        coef = np.array(model.coef_).reshape(-1)\n        return pd.Series(np.abs(coef), index=feat_cols[:len(coef)]).sort_values(ascending=False)\n    if hasattr(model, "estimators_"):\n        parts = []\n        for est in model.estimators_:\n            if hasattr(est, "feature_importances_"):\n                parts.append(pd.Series(est.feature_importances_, index=feat_cols))\n            elif hasattr(est, "coef_"):\n                coef = np.array(est.coef_).reshape(-1)\n                parts.append(pd.Series(np.abs(coef), index=feat_cols[:len(coef)]))\n        if parts:\n            return pd.concat(parts, axis=1).mean(axis=1).sort_values(ascending=False)\n    return pd.Series(0, index=feat_cols)\n\ndef validation_grade(conf, corr, test_rows):\n    if test_rows < 5:\n        return "Weak: too few test rows"\n    if corr > .10 and conf > .50:\n        return "Good"\n    if corr > .03 and conf > .33:\n        return "Acceptable"\n    if corr > 0:\n        return "Weak but positive"\n    return "Weak / negative"\n\ndef stance(signal, conf, corr, test_rows):\n    grade = validation_grade(conf, corr, test_rows)\n    goodish = grade in ["Good","Acceptable"]\n    if signal == "Bullish" and conf >= .60 and goodish:\n        return "ML-only BUY WATCH"\n    if signal == "Bearish" and conf >= .60 and goodish:\n        return "ML-only SELL / RISK WATCH"\n    if signal == "Bullish" and conf >= .33 and corr > -0.02:\n        return "ML-only BULLISH / KEEP WATCH"\n    if signal == "Bearish" and conf >= .33 and corr > -0.02:\n        return "ML-only BEARISH / PROTECT WATCH"\n    return "ML-only KEEP / NO ACTION"\n\ndef train_one(asset, prices, features, requested_horizon, model_name, feat_cols, interval):\n    if asset not in prices.columns:\n        return None, None, "no price"\n    px = prices[asset].dropna()\n    if len(px) < 12:\n        return None, None, "not enough price rows"\n\n    n = min(len(px), len(features))\n    effective_horizon = max(1, min(int(requested_horizon), max(1, n//8)))\n\n    def dataset(h):\n        y = prices[asset].pct_change(h).shift(-h).rename("future_return")\n        X = features[feat_cols].copy()\n        return pd.concat([X, y], axis=1, join="inner").dropna(subset=["future_return"])\n\n    df = dataset(effective_horizon)\n    if len(df) < 25:\n        effective_horizon = max(1, min(5, requested_horizon))\n        df = dataset(effective_horizon)\n    if len(df) < 16:\n        effective_horizon = 1\n        df = dataset(1)\n    if len(df) < 12:\n        return None, None, "not enough rows"\n\n    # Fill feature gaps after target cleaning.\n    df[feat_cols] = df[feat_cols].fillna(0)\n\n    split = max(8, int(len(df)*.70))\n    if split >= len(df)-3:\n        split = max(6, len(df)-4)\n    tr, te = df.iloc[:split], df.iloc[split:]\n    if len(te) < 2:\n        return None, None, "too few test rows"\n\n    Xtr, ytr = tr[feat_cols], tr["future_return"].astype(float)\n    Xte, yte = te[feat_cols], te["future_return"].astype(float)\n\n    candidates = model_candidates()\n    if model_name == "AutoBest":\n        best = None\n        for nm, model in candidates.items():\n            try:\n                m, pred, corr, rmse, score = fit_eval(model, Xtr, ytr, Xte, yte)\n                if best is None or score > best["score"]:\n                    best = {"name":nm, "model":m, "pred":pred, "corr":corr, "rmse":rmse, "score":score}\n            except Exception:\n                pass\n        if best is None:\n            return None, None, "models failed"\n        selected_model = best["name"]\n        model, pred, corr, rmse = best["model"], best["pred"], best["corr"], best["rmse"]\n    else:\n        try:\n            model, pred, corr, rmse, _ = fit_eval(candidates.get(model_name, Ridge(alpha=8)), Xtr, ytr, Xte, yte)\n            selected_model = model_name\n        except Exception:\n            return None, None, "model failed"\n\n    latest_pred = float(model.predict(features.iloc[[-1]][feat_cols].fillna(0))[0])\n    vol = max(float(ytr.std()), 1e-6)\n    conf = min(abs(latest_pred)/(vol*1.25), 1)\n    sig = "Bullish" if latest_pred > 0 else "Bearish"\n    inten = "Strong" if conf > .66 else "Moderate" if conf > .33 else "Weak"\n    grade = validation_grade(conf, corr, len(te))\n    final = stance(sig, conf, corr, len(te))\n\n    imp = feature_importance(model, feat_cols)\n    d1 = imp.index[0] if len(imp)>0 else ""\n    d2 = imp.index[1] if len(imp)>1 else ""\n    d3 = imp.index[2] if len(imp)>2 else ""\n\n    te2 = te.copy()\n    te2["prediction"] = pred\n    te2["position"] = np.where(te2["prediction"] > 0, 1, -1)\n    te2["strategy_return_net"] = te2["position"]*te2["future_return"] - .0005*pd.Series(te2["position"], index=te2.index).diff().abs().fillna(1)\n    te2["equity_net"] = (1+te2["strategy_return_net"].fillna(0)).cumprod()\n    dd = float((te2["equity_net"]/te2["equity_net"].cummax()-1).min()) if len(te2) else 0\n\n    last_price_date = px.index[-1]\n    vu = valid_until(last_price_date, interval, effective_horizon)\n    vu_str = str(vu)\n\n    first_date = str(pd.Timestamp(df.index[0]))\n    last_date = str(pd.Timestamp(df.index[-1]))\n\n    reason = f"{selected_model} estimated {sig.lower()} pressure over {effective_horizon} {interval} bars. Main drivers: {d1}, {d2}, {d3}."\n    final_message = f"{final}. Valid research window: until approximately {vu_str}. Data coverage: {first_date} to {last_date}. Validation: {grade}; test corr {corr:.3f}; confidence {conf:.2f}. {reason} ML-only, not financial advice."\n\n    row = {\n        "asset": asset, "selected_model": selected_model, "signal": sig, "final_ml_stance": final,\n        "bull_bear_score": float((1 if sig=="Bullish" else -1)*conf*max(min(corr+.25,1),0)),\n        "intensity": inten, "prediction": latest_pred, "confidence": conf, "test_corr": corr,\n        "validation_grade": grade, "rmse": rmse, "max_drawdown_toy": dd, "requested_horizon": requested_horizon,\n        "effective_horizon": effective_horizon, "interval": interval, "valid_until_est": vu_str,\n        "data_start": first_date, "data_end": last_date, "train_rows": len(tr), "test_rows": len(te),\n        "driver_1": d1, "driver_2": d2, "driver_3": d3, "ml_reason": reason, "final_message": final_message\n    }\n    return row, te2, None\n\n@st.cache_data(ttl=120, show_spinner=False)\ndef options_chain(ticker, expiry=None):\n    try:\n        tk = yf.Ticker(ticker)\n        expiries = list(tk.options)\n        if not expiries:\n            return expiries, pd.DataFrame(), pd.DataFrame()\n        exp = expiry if expiry in expiries else expiries[0]\n        ch = tk.option_chain(exp)\n        return expiries, ch.calls.copy(), ch.puts.copy()\n    except Exception:\n        return [], pd.DataFrame(), pd.DataFrame()\n\ndef make_query(terms):\n    clean = [x.strip() for x in terms if x.strip()]\n    return "(" + " OR ".join(clean) + ")" if clean else "(critical minerals OR rare earth OR oil OR gas OR gold OR silver)"\n\ndef regime(latest, gscore):\n    gc = latest.get("GCMSI", 0)\n    vix = latest.get("MACRO:VIX", 0)\n    usd = latest.get("MACRO:USDIndex", 0)\n    energy = latest.get("FAMILY:energy_inputs", 0)\n    if gscore >= 2.5 and gc > .4:\n        return "Geopolitical materials shock"\n    if gc > 1.2 and vix > .8:\n        return "Risk-off industrial stress"\n    if energy > 1.1:\n        return "Energy / fuel cost shock"\n    if usd > 1.0 and gc > .3:\n        return "USD commodity pressure"\n    if gc > .8:\n        return "Commodity stress"\n    if gc < -.8:\n        return "Stress easing"\n    return "Normal / mixed"\n\n# --------------------------\n# UI\n# --------------------------\nst.set_page_config(page_title="MatQuantLab V10 Universal", layout="wide")\nst.title("MatQuantLab V10 — Universal Interval Critical Materials Terminal")\nst.caption("Runs from 1-minute monitoring to 10-year daily ML mode with adaptive features and fallback logic.")\n\nidx_df = flatten_indices(indices_cfg)\ncore_assets = sorted(set(exposure["asset"].astype(str).tolist() + ["SPY","XME","COPX","ITA","XAR","PRNT","SOXX","XLE","URA","LIT","REMX","SLX","GLD","SLV","USO","UNG"]))\ncompany_assets = sorted(company_universe["ticker"].dropna().astype(str).unique().tolist()) if not company_universe.empty else []\nfuture_assets = sorted(set(FUTURES_UNIVERSE.values()))\nall_assets = sorted(set(core_assets + company_assets + future_assets))\ndefaults = [x for x in ["SPY","COPX","XME","GLD","SLV","USO","URA","LIT","REMX","SOXX"] if x in all_assets]\n\nwith st.sidebar:\n    st.header("Controls")\n    with st.expander("Why V10 should not crash", expanded=True):\n        st.markdown("- Invalid intraday/long-history combinations are automatically adjusted.")\n        st.markdown("- Shock window is automatically reduced when the dataset is short.")\n        st.markdown("- If material/future features fail, fallback price features are built from downloaded tickers.")\n        st.markdown("- Use `Raw Data` to see actual period and feature status.")\n\n    asset_mode = st.radio("Asset universe", ["Core ETFs/stocks", "Manufacturing companies", "Commodities/futures/proxies", "Everything"], index=3)\n    country_filter = []\n    if not company_universe.empty:\n        country_filter = st.multiselect("Filter manufacturing countries", sorted(company_universe["country"].dropna().unique().tolist()), default=[])\n\n    if asset_mode == "Core ETFs/stocks":\n        choices = core_assets\n    elif asset_mode == "Manufacturing companies":\n        choices = company_assets\n    elif asset_mode == "Commodities/futures/proxies":\n        choices = future_assets\n    else:\n        choices = all_assets\n\n    if country_filter and not company_universe.empty:\n        country_tickers = company_universe.loc[company_universe["country"].isin(country_filter), "ticker"].astype(str).tolist()\n        if asset_mode == "Manufacturing companies":\n            choices = sorted(set(country_tickers))\n        elif asset_mode == "Everything":\n            choices = sorted(set(core_assets + future_assets + country_tickers))\n\n    assets = st.multiselect("Assets to predict", choices, default=[x for x in defaults if x in choices][:10])\n    interval = st.selectbox("Refresh / data interval", ["1m","5m","15m","30m","60m","1d"], index=5)\n    period = st.selectbox("Lookback period", ["1d","5d","1mo","3mo","6mo","1y","2y","5y","10y"], index=7)\n    model_name = st.selectbox("Model", ["AutoBest","Ridge","ElasticNet","Huber","RandomForest","ExtraTrees","GradientBoosting","Ensemble"], index=0)\n    horizon = st.slider("Prediction horizon in bars", 1, 120, 10)\n    shock_window = st.slider("Shock window in bars", 2, 150, 20)\n    max_news = st.slider("News items", 10, 150, 80)\n\n    terms = st.multiselect(\n        "News terms",\n        sorted(set(DEFAULT_GEO_TERMS + geo_cfg.get("default_terms", []) + ["Middle East","Iran","Israel","Red Sea","Houthis","Strait of Hormuz","fuel","gas","LNG","VIX","China","Taiwan","semiconductors","uranium","titanium","gold","silver","copper","aluminum","lithium","graphite"])),\n        default=geo_cfg.get("default_terms", DEFAULT_GEO_TERMS)[:20] if isinstance(geo_cfg.get("default_terms", DEFAULT_GEO_TERMS), list) else DEFAULT_GEO_TERMS\n    )\n    extra = st.text_input("Extra terms, comma separated", value="")\n    if extra:\n        terms += [x.strip() for x in extra.split(",") if x.strip()]\n\n    auto = st.toggle("Auto-refresh", value=False)\n    seconds = st.selectbox("Auto-refresh seconds", [20,30,60,120,300], index=2)\n    if st.button("Force refresh"):\n        st.cache_data.clear()\n        st.rerun()\n\nif auto:\n    time.sleep(seconds)\n    st.cache_data.clear()\n    st.rerun()\n\nactual_period = universal_period(interval, period)\nquery = make_query(terms)\nmacro_tickers = list(macro_cfg.values())\ntickers = sorted(set(assets + material_tickers(materials_cfg) + macro_tickers + idx_df.get("ticker", pd.Series(dtype=str)).dropna().tolist() + list(FUTURES_UNIVERSE.values())))\n\nprices = download_prices(tickers, actual_period, interval)\nif prices.empty:\n    st.error("No prices downloaded. Try fewer tickers, interval=1d, period=5y, or use Core ETFs/stocks.")\n    st.stop()\n\nfeatures, meta, proxy_table, effective_shock, feature_status = build_features(prices, materials_cfg, macro_cfg, shock_window)\nif features.empty:\n    st.error(f"No features built even after fallback. Reason: {feature_status}. Try selecting SPY/GLD/USO/XME and interval=1d.")\n    st.stop()\n\ngd = gdelt(query, max_news)\ngnews = google_news_rss(query, max_records=min(max_news, 50))\nrss, rss_status = rss_fetch(news_sources, max_per=10)\nnews = pd.concat([x for x in [gd, gnews, rss] if not x.empty], ignore_index=True) if (not gd.empty or not gnews.empty or not rss.empty) else pd.DataFrame()\ngscore, gthemes = score_news(news)\n\nlatest = features.iloc[-1]\nreg = regime(latest, gscore)\nfeat_cols = [c for c in features.columns if c != "GCMSI" or c == "GCMSI"]\n# avoid all-NaN columns\nfeat_cols = [c for c in feat_cols if features[c].notna().sum() >= max(3, min(20, len(features)//5))]\nif "GCMSI" not in feat_cols and "GCMSI" in features.columns:\n    feat_cols.append("GCMSI")\nfeat_cols = list(dict.fromkeys(feat_cols))\n\npred_rows, curves = [], {}\nfor a in assets:\n    row, curve, err = train_one(a, prices, features, horizon, model_name, feat_cols, interval)\n    if row:\n        # Annotate\n        exp = exposure.loc[exposure["asset"].astype(str) == a]\n        comp = company_universe.loc[company_universe["ticker"].astype(str) == a] if not company_universe.empty else pd.DataFrame()\n        if len(exp):\n            row["full_name"] = exp.iloc[0].get("full_name", "")\n            row["theme"] = exp.iloc[0].get("theme", "")\n            row["country"] = exp.iloc[0].get("region", "")\n            row["industry_group"] = row["theme"]\n        if len(comp):\n            row["full_name"] = comp.iloc[0].get("company", row.get("full_name", ""))\n            row["theme"] = comp.iloc[0].get("material_link", row.get("theme", ""))\n            row["country"] = comp.iloc[0].get("country", row.get("country", ""))\n            row["industry_group"] = comp.iloc[0].get("industry_group", "")\n        if not row.get("full_name"):\n            row["full_name"] = next((k for k, v in FUTURES_UNIVERSE.items() if v == a), a)\n            row["theme"] = "Commodity/future/proxy"\n            row["country"] = "Global"\n            row["industry_group"] = "Futures / macro / commodity"\n        pred_rows.append(row)\n        curves[a] = curve\n\npred = pd.DataFrame(pred_rows).sort_values(["confidence","test_corr"], ascending=[False,False]) if pred_rows else pd.DataFrame()\n\n# Header metrics\nc1,c2,c3,c4,c5,c6,c7,c8 = st.columns(8)\nc1.metric("GCMSI", f"{latest.get(\'GCMSI\',0):.2f}")\nc2.metric("Regime", reg)\nc3.metric("Geo/news", f"{gscore:.2f}")\nc4.metric("Tickers", prices.shape[1])\nc5.metric("Features", features.shape[1])\nc6.metric("Predictions", len(pred))\nc7.metric("Actual period", actual_period)\nc8.metric("Shock used", effective_shock)\n\nif actual_period != period:\n    st.warning(f"Requested {period} with interval {interval}, but Yahoo intraday limits require using {actual_period}. For 5y/10y, use interval=1d.")\nst.success(f"Feature status: {feature_status}. Price coverage: {prices.index[0]} → {prices.index[-1]}.")\n\ntabs = st.tabs([\n    "Control Guide",\n    "ML Signal Summary",\n    "Detailed Prediction",\n    "Radar + Drivers",\n    "Commodities/Futures",\n    "Stocks/Companies",\n    "Options",\n    "News",\n    "Global/Macro",\n    "Raw Data"\n])\n\nwith tabs[0]:\n    st.subheader("Universal interval guide")\n    for k, v in DEFINITIONS.items():\n        st.markdown(f"**{k}:** {v}")\n    st.markdown("""\n### Which setting should you use?\n- **1m / 1d or 5d**: very fast monitoring, noisy, weak ML.\n- **5m or 15m / 5d to 1mo**: short-term terminal monitoring.\n- **1d / 1y, 2y, 5y, 10y**: best for proper ML and realistic validation.\n- **If you want “past 5 years until now,” choose interval = 1d and period = 5y.**\n- **If you want 10-year macro/material regime view, choose interval = 1d and period = 10y.**\n""")\n    st.markdown("### Why the old version failed")\n    st.write("It required material/macro features to exist after rolling z-score cleaning. If Yahoo did not return enough direct material/future data, the feature table became empty. V10 now builds fallback features from whatever prices actually downloaded.")\n\nwith tabs[1]:\n    st.subheader("ML-only final stance table")\n    explain_box("ML Signal Summary", [\n        "Each selected asset gets its own model.",\n        "AutoBest tries multiple models and picks the best validation score.",\n        "Valid-until is estimated from interval × effective horizon.",\n        "Data_start/data_end show what was actually used.",\n        "BUY/SELL labels are ML-only research labels, not advice."\n    ])\n    if pred.empty:\n        st.warning("No predictions. Try selecting SPY/GLD/USO, interval=1d, period=5y, model=AutoBest.")\n    else:\n        cols = ["asset","full_name","country","industry_group","selected_model","final_ml_stance","signal","intensity","prediction","confidence","test_corr","validation_grade","driver_1","driver_2","driver_3","effective_horizon","valid_until_est","data_start","data_end","final_message"]\n        st.dataframe(pred[cols], use_container_width=True)\n        plot_bar(pred["final_ml_stance"].value_counts(), "Count of ML-only stances")\n\nwith tabs[2]:\n    st.subheader("Detailed prediction")\n    if pred.empty:\n        st.warning("No detailed prediction available.")\n    else:\n        chosen = st.selectbox("Choose asset", pred["asset"].tolist())\n        row = pred[pred["asset"] == chosen].iloc[0]\n        st.markdown(f"## {chosen} — {row.get(\'full_name\',\'\')}")\n        a,b,c,d,e = st.columns(5)\n        a.metric("Final stance", row["final_ml_stance"])\n        b.metric("Model", row["selected_model"])\n        c.metric("Confidence", f"{row[\'confidence\']:.2f}")\n        d.metric("Test corr", f"{row[\'test_corr\']:.3f}")\n        e.metric("Valid until", str(row["valid_until_est"])[:16])\n        st.markdown("### Final message")\n        st.write(row["final_message"])\n        st.markdown("### Reason")\n        st.write(row["ml_reason"])\n        if chosen in curves:\n            plot_lines(curves[chosen][["prediction","future_return"]], f"{chosen}: prediction vs realized future return", "return")\n            st.caption("If prediction and future_return move together historically, the model had alignment. If not, downgrade the signal.")\n            plot_lines(curves[chosen][["equity_net"]], f"{chosen}: toy net equity curve", "equity")\n            st.caption("Toy equity is only a sanity check with a simple cost placeholder, not a production backtest.")\n\nwith tabs[3]:\n    st.subheader("Radar + strongest drivers")\n    radar_cols = [c for c in ["GCMSI","FAMILY:industrial_metals","FAMILY:steel_chain","FAMILY:battery_materials","FAMILY:rare_earths","FAMILY:aerospace_defense_materials","FAMILY:energy_inputs","FAMILY:precious_stress","FAMILY:precious_industrial","FAMILY:macro","FAMILY:fallback_price","REGIME:RiskOff","REGIME:USDPressure"] if c in features.columns]\n    plot_lines(features[radar_cols], "Global stress radar", "z-score stress")\n    explain_box("Radar", [\n        "Positive lines mean unusually high/upward stress or momentum.",\n        "Negative lines mean easing or downside pressure.",\n        "GCMSI combines the available material, macro and fallback features.",\n        "If FAMILY:fallback_price appears, it means the app used available price features because some material configs/futures did not return enough data."\n    ])\n    drivers = latest[[c for c in features.columns if c != "GCMSI"]].sort_values(key=lambda s: s.abs(), ascending=False).head(35)\n    plot_bar(drivers, "Current strongest drivers")\n    explain_box("Drivers", [\n        "Right side = positive/upward z-score.",\n        "Left side = negative/easing z-score.",\n        "Largest absolute bars are the strongest current abnormal moves.",\n        "Compare these with driver_1/2/3 in the prediction table."\n    ])\n\nwith tabs[4]:\n    st.subheader("Commodities, futures and proxies")\n    fdf = pd.DataFrame([{"instrument": k, "ticker": v, "downloaded": v in prices.columns} for k, v in FUTURES_UNIVERSE.items()])\n    st.dataframe(fdf, use_container_width=True)\n    downloaded = [t for t in fdf.loc[fdf["downloaded"], "ticker"].tolist() if t in prices.columns]\n    selected_f = st.multiselect("Chart futures/proxies", downloaded, default=downloaded[:10])\n    if selected_f:\n        plot_lines(prices[selected_f], "Commodity/future/proxy prices", "normalized", normalize=True)\n        st.caption("Normalized means every series starts at 1 so oil, gas, gold, copper and ETFs can be compared.")\n    st.markdown("### Material proxy resolution")\n    st.dataframe(proxy_table, use_container_width=True)\n\nwith tabs[5]:\n    st.subheader("Stocks / manufacturing companies")\n    if company_universe.empty:\n        st.warning("Company universe missing.")\n    else:\n        countries = st.multiselect("Country filter", sorted(company_universe["country"].dropna().unique().tolist()), default=country_filter)\n        table = company_universe.copy()\n        if countries:\n            table = table[table["country"].isin(countries)]\n        st.dataframe(table, use_container_width=True)\n        plot_bar(table.groupby("country")["ticker"].count().sort_values(ascending=False), "Companies by country")\n        st.caption("Some foreign tickers may not download for every interval. Daily data is usually more stable than intraday.")\n\nwith tabs[6]:\n    st.subheader("Options")\n    opt_asset = st.selectbox("Options ticker", assets if assets else ["SPY","XME","COPX","GLD","SLV","USO"])\n    expiries, calls, puts = options_chain(opt_asset)\n    if not expiries:\n        st.warning("No Yahoo options found. Try SPY, XME, COPX, ITA, XLE, GLD, SLV, USO.")\n    else:\n        exp = st.selectbox("Expiration", expiries)\n        expiries, calls, puts = options_chain(opt_asset, exp)\n        cvol = calls["volume"].fillna(0).sum() if not calls.empty else 0\n        pvol = puts["volume"].fillna(0).sum() if not puts.empty else 0\n        coi = calls["openInterest"].fillna(0).sum() if not calls.empty else 0\n        poi = puts["openInterest"].fillna(0).sum() if not puts.empty else 0\n        a,b,c,d = st.columns(4)\n        a.metric("Call volume", int(cvol)); b.metric("Put volume", int(pvol)); c.metric("Put/Call volume", f"{pvol/max(cvol,1):.2f}"); d.metric("Put/Call OI", f"{poi/max(coi,1):.2f}")\n        st.dataframe(calls[["contractSymbol","strike","lastPrice","bid","ask","volume","openInterest","impliedVolatility"]].sort_values("openInterest", ascending=False).head(50), use_container_width=True)\n        st.dataframe(puts[["contractSymbol","strike","lastPrice","bid","ask","volume","openInterest","impliedVolatility"]].sort_values("openInterest", ascending=False).head(50), use_container_width=True)\n\nwith tabs[7]:\n    st.subheader("News")\n    st.write(f"Query: `{query}`")\n    st.metric("News risk score", f"{gscore:.2f}")\n    status = pd.DataFrame([\n        {"source":"GDELT", "ok":not gd.empty, "articles_loaded":len(gd), "focus":"query news"},\n        {"source":"Google News RSS", "ok":not gnews.empty, "articles_loaded":len(gnews), "focus":"query RSS"},\n    ])\n    if not rss_status.empty:\n        status = pd.concat([status, rss_status[["source","ok","articles_loaded","focus"]]], ignore_index=True)\n    st.dataframe(status, use_container_width=True)\n    if not gthemes.empty:\n        st.dataframe(gthemes, use_container_width=True)\n        plot_bar(gthemes.set_index("long_name")["weighted_score"], "News theme intensity")\n    if news.empty:\n        st.warning("No news returned. Use fewer terms or simpler query.")\n    else:\n        st.dataframe(news[["title","source","country","date","url"]].head(150), use_container_width=True)\n\nwith tabs[8]:\n    st.subheader("Global / macro")\n    region = st.selectbox("Region", sorted(idx_df["region"].unique()) if not idx_df.empty else [])\n    if region:\n        rts = [t for t in idx_df[idx_df["region"] == region]["ticker"].tolist() if t in prices.columns]\n        if rts:\n            plot_lines(prices[rts], f"{region} index proxies", "normalized", normalize=True)\n    macro_cols = [c for c in features.columns if c.startswith("MACRO:")]\n    if macro_cols:\n        plot_lines(features[macro_cols], "Macro stress features", "z-score")\n\nwith tabs[9]:\n    st.subheader("Raw data and diagnostics")\n    st.write(f"Requested period: `{period}` | Actual period used: `{actual_period}` | Interval: `{interval}` | Effective shock window: `{effective_shock}`")\n    st.write(f"Feature status: `{feature_status}`")\n    st.write(f"Price coverage: `{prices.index[0]}` → `{prices.index[-1]}`")\n    st.write(f"Feature rows: `{len(features)}` | Feature columns: `{features.shape[1]}`")\n    st.dataframe(prices.tail(100), use_container_width=True)\n    st.dataframe(features.tail(100), use_container_width=True)\n    st.dataframe(meta, use_container_width=True)\n\nst.divider()\nst.caption("Data: Yahoo Finance via yfinance + GDELT/Google/RSS feeds. Free data can be delayed/incomplete. ML labels are research outputs, not financial advice.")\n')
